# ==========================================================
# STUDENT DATABASE FUNCTIONS
# ==========================================================

def get_student(student_id):

    conn = connect()

    student = conn.execute("""
        SELECT *
        FROM students
        WHERE student_id = ?
    """, (student_id,)).fetchone()

    conn.close()

    return student


def get_subjects(student):
    conn = connect()
    semester = student["semester"] if "semester" in student.keys() else "Current"
    subjects = conn.execute("""
        SELECT * FROM subjects
        WHERE year=? AND branch=? AND section=?
          AND (semester=? OR semester='Current' OR semester='')
        ORDER BY subject_name
    """, (student["year"], student["branch"], student["section"], semester)).fetchall()
    conn.close()
    return subjects

def get_timetable(student):

    conn = connect()

    timetable = conn.execute("""
        SELECT *
        FROM timetables
        WHERE year = ?
        AND branch = ?
        AND section = ?
    """, (
        student["year"],
        student["branch"],
        student["section"]
    )).fetchone()

    conn.close()

    return timetable


def get_attendance(student_id, subject_id):

    conn = connect()

    total = conn.execute("""
        SELECT COUNT(*) AS total
        FROM attendance
        WHERE student_id = ?
        AND subject_id = ?
    """, (
        student_id,
        subject_id
    )).fetchone()["total"]

    attended = conn.execute("""
        SELECT COUNT(*) AS attended
        FROM attendance
        WHERE student_id = ?
        AND subject_id = ?
        AND status = 'Present'
    """, (
        student_id,
        subject_id
    )).fetchone()["attended"]

    conn.close()

    absent = total - attended

    if total > 0:
        percentage = (attended / total) * 100
    else:
        percentage = 0

    return total, attended, absent, percentage


